def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    used = set()

    # The repeated square motif is colored 1.
    for r in range(h - 1):
        for c in range(w - 1):
            cells = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if all(grid[y][x] == 8 for y, x in cells):
                for y, x in cells:
                    out[y][x] = 1
                    used.add((y, x))

    # Color remaining cells in connected groups, assigning the remaining
    # motif colors in scan order.
    remaining = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == 8 and (r, c) not in used}
    colors = [2, 3, 4]
    while remaining:
        start = min(remaining)
        stack = [start]
        component = set()
        remaining.remove(start)
        while stack:
            r, c = stack.pop()
            component.add((r, c))
            for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (y, x) in remaining:
                    remaining.remove((y, x))
                    stack.append((y, x))
        color = colors.pop(0) if colors else 2
        for r, c in component:
            out[r][c] = color
    return out
