        for c in range(w - 1):
            sq = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if sq <= occupied:
                blocks.append(sq)
    for sq in blocks:
        for r, c in sq:
            out[r][c] = 1

    # Remaining cells form small protrusions; color connected groups by
    # their position around the marked square blocks.
    rest = {p for p in occupied if out[p[0]][p[1]] == 0}
    while rest:
        seed = min(rest)
        comp = {seed}
        stack = [seed]
        rest.remove(seed)
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in rest:
                    rest.remove(p)
                    comp.add(p)
                    stack.append(p)
        # Directional color convention for the protrusion components.
        r, c = min(comp)
        if r <= 1:
            color = 3 if c <= 1 else 4
        else:
            color = 2
        for r, c in comp:
            out[r][c] = color

    # Non-square occupied cells adjacent to a square can belong to a
    # different lobe; use local position to separate those lobes.
    for r, c in occupied:
